If you prefer the Vue 2 style where Axios is available on `this`, or you want it globally accessible in Vue 3 templates via a global property:

**In `main.js`:**
```javascript
import { createApp } from 'vue';
import App from './App.vue';
import api from './services/api';

const app = createApp(App);

// Set as a global property
app.config.globalProperties.$api = api;

app.mount('#app');
