export function validateRequest<T>(
  schema: {
    body?: (data: unknown) => T;
    query?: (data: unknown) => Record<string, string | string[]>;
    params?: (data: unknown) => Record<string, string>;
  }
): RequestHandler {
  return (req: TypedRequest, _res: Response, next: NextFunction): void => {
    try {
      if (schema.body) {
        req.body = schema.body(req.body);
      }
      if (schema.query) {
        req.query = schema.query(req.query);
      }
      if (schema.params) {
        req.params = schema.params(req.params);
      }
      next();
    } catch (error) {
      if (isApiError(error)) {
        next(error);
      } else {
        next(ApiError.validation({
          ...(error instanceof Error ? { general: [error.message] } : {}),
        }));
      }
    }
  };
}

