interface PaymentIntentSucceeded extends WebhookBase {
  type: 'payment_intent.succeeded';
  data: {
    object: {
      id: string;
      customer_email: string;
      amount: number;
    };
  };
}

interface PaymentIntentFailed extends WebhookBase {
  type: 'payment_intent.payment_failed';
  data: {
    object: {
      id: string;
      last_payment_error: {
        code: string;
      } | null;
    };
  };
}

type WebhookEvent = PaymentIntentSucceeded | PaymentIntentFailed;

async function handleWebhook(payload: unknown) {
  const event = payload as WebhookEvent;

  switch (event.type) {
    case 'payment_intent.succeeded':
      // TS now knows event.data.object contains customer_email and amount
      await db.payments.update({
        id: event.data.object.id,
        status: 'completed',
        email: event.data.object.customer_email,
        amount: event.data.object.amount
      });
      break;
    case 'payment_intent.payment_failed':
      // TS now knows event.data.object contains last_payment_error
      await db.logs.create({
        eventId: event.id,
        error: event.data.object.last_payment_error?.code || 'Unknown Error'
      });
      break;
  }
}
```

This migration prevents the 'Cannot read property X of undefined' bug class specifically when the payload type is recognized but the internal object structure differs between event types. By using a Discriminated Union, you move the validation from a runtime gamble to a compile-time requirement.

