```ts
type Observation = {
  kind: string;
  seenAt: string;
  notes?: string;
};

export function formatObservations(observations: Observation[]): string {
  if (observations.length === 0) return '';

  const sorted = [...observations].sort((a, b) => 
    new Date(a.seenAt).getTime() - new Date(b.seenAt)
  );

  return sorted
    .map((obs, index) => `${index + 1}. ${obs.kind} at ${obs.seenAt}${obs.notes ? ` - ${obs.notes}` : ''}`)
    .join('\n');
}

export function latestKinds(observations: Observation[]): string[] {
  if (observations.length === 0) return [];

  const latest = observations.reduce((acc, obs) => {
    const currentLatest = acc[obs.kind];
    if (!currentLatest || new Date(obs.seenAt).getTime() > new Date(currentLatest).getTime()) {
      acc[obs.kind] = obs.seenAt;
    }
    return acc;
  }, {} as Record<string, string>);

  return Object.keys(latest).sort();
}
```

## Key Changes

| Issue | Fix |
|-------|-----|
| Array mutation | Spread `[...observations]` before sorting |
| Date comparison | Use `Date.getTime()` instead of `localeCompare` for numeric comparison |
| `latestKinds` logic | Compare actual dates to find true latest per kind |
| Empty arrays | Early return with explicit `if` checks |

## Additional Suggestions

1. **Consider returning observation objects** from `latestKinds` instead of just kind names
2. **Add input validation** if `seenAt` format isn't guaranteed
3. **Consider a `deduplicate` utility** if duplicate entries are a concern

