interface PaymentIntentFailed extends WebhookBase {
  type: 'payment_intent.payment_failed';
  data: {
    object: {
      id: string;
      // Optional property handles the key being entirely missing from JSON
      last_payment_error?: {
        code: string;
      } | null;
    };
  };
}

async function handleWebhook(payload: unknown) {
  const event = payload as WebhookEvent;

  switch (event.type) {
    case 'payment_intent.succeeded':
      await db.payments.update({
        id: event.data.object.id,
        status: 'completed',
        // Use nullish coalescing to provide a fallback for the optional field
        email: event.data.object.customer_email ?? '[REDACTED]',
        amount: event.data.object.amount
      });
      break;
    case 'payment_intent.payment_failed':
      await db.logs.create({
        eventId: event.id,
        // Optional chaining handles both the missing key and the null value
        error: event.data.object.last_payment_error?.code ?? 'Unknown Error'
      });
      break;
  }
}
```

By adding `?` to `customer_email` and `last_payment_error`, TypeScript will stop you from passing these values directly into a function that requires a `string`. This forces you to use `??` or `?.`, ensuring that the 'missing key' edge case is handled explicitly without the performance hit of a schema validation library.

