// Database implementation
type DBPolicyRepository struct {
    db *sql.DB
}

func (r *DBPolicyRepository) GetMinAgeForRole(role string) (int, error) {
    var age int
    err := r.db.QueryRow("SELECT min_age FROM role_policies WHERE role = ?", role).Scan(&age)
    if err != nil {
        return 0, err
    }
    return age, nil
}

func (r *DBPolicyRepository) GetMaxAgeForRole(role string) (int, error) {
    var age int
    err := r.db.QueryRow("SELECT max_age FROM role_policies WHERE role = ?", role).Scan(&age)
    if err != nil {
        return 0, err
    }
    return age, nil
}
